// ── CELEBRATION CALENDAR ──────────────────────────────────────────────
// Checks today's date and upcoming celebrations (7-day warning + day-of)
// Returns array of celebrations needing messages today.

const today = new Date();
const todayStr = today.toISOString().split('T')[0];
const in7 = new Date(today); in7.setDate(in7.getDate() + 7);
const in3 = new Date(today); in3.setDate(in3.getDate() + 3);
const in1 = new Date(today); in1.setDate(in1.getDate() + 1);

// Load templates from JSON file (uploaded to n8n)
// In production: read from HTTP Request node pointing to your server
// For now we embed the top 30 celebrations inline
const celebrations = [
  { date: '2026-01-01', name: "New Year's Day", emoji: '🎆', discount: 15, code: 'NEWYEAR26', theme: 'new_year' },
  { date: '2026-02-14', name: "Valentine's Day", emoji: '❤️', discount: 20, code: 'LOVE26', theme: 'valentine' },
  { date: '2026-03-17', name: "St. Patrick's Day", emoji: '☘️', discount: 17, code: 'STPAT26', theme: 'st_patricks' },
  { date: '2026-04-05', name: 'Easter Sunday', emoji: '🐣', discount: 20, code: 'EASTER26', theme: 'easter' },
  { date: '2026-05-10', name: "Mother's Day", emoji: '🌹', discount: 25, code: 'MOM26', theme: 'mothers_day' },
  { date: '2026-05-25', name: 'Memorial Day', emoji: '🎖️', discount: 15, code: 'MEMORIAL26', theme: 'military' },
  { date: '2026-06-21', name: "Father's Day", emoji: '👔', discount: 25, code: 'DAD26', theme: 'fathers_day' },
  { date: '2026-07-04', name: 'Independence Day', emoji: '🎆', discount: 20, code: 'JULY426', theme: 'fourth_july' },
  { date: '2026-07-30', name: 'Friendship Day', emoji: '👫', discount: 15, code: 'FRIEND26', theme: 'friendship' },
  { date: '2026-09-07', name: 'Labor Day', emoji: '👷', discount: 20, code: 'LABOR26', theme: 'holiday' },
  { date: '2026-09-13', name: 'Grandparents Day', emoji: '👴👵', discount: 20, code: 'GRAND26', theme: 'grandparents' },
  { date: '2026-10-31', name: 'Halloween', emoji: '🎃', discount: 20, code: 'HALLOW26', theme: 'halloween' },
  { date: '2026-11-11', name: 'Veterans Day', emoji: '🎖️', discount: 20, code: 'VET26', theme: 'military' },
  { date: '2026-11-26', name: 'Thanksgiving', emoji: '🦃', discount: 20, code: 'THANKS26', theme: 'thanksgiving' },
  { date: '2026-11-27', name: 'Black Friday', emoji: '🛍️', discount: 30, code: 'BLACK26', theme: 'sale' },
  { date: '2026-12-01', name: 'Cyber Monday', emoji: '💻', discount: 25, code: 'CYBER26', theme: 'sale' },
  { date: '2026-12-25', name: 'Christmas Day', emoji: '🎄', discount: 25, code: 'XMAS26', theme: 'christmas' },
  { date: '2026-12-31', name: "New Year's Eve", emoji: '🥂', discount: 20, code: 'NYE26', theme: 'new_year' },
  { date: '2026-03-08', name: "International Women's Day", emoji: '👩', discount: 15, code: 'WOMENS26', theme: 'womens_day' },
  { date: '2026-04-25', name: 'Administrative Professionals Day', emoji: '📋', discount: 15, code: 'ADMIN26', theme: 'corporate' },
  { date: '2026-05-05', name: 'Cinco de Mayo', emoji: '🌮', discount: 15, code: 'CINCO26', theme: 'cultural' },
];

const toSend = [];

for (const cel of celebrations) {
  const celDate = new Date(cel.date);
  const celDateStr = celDate.toISOString().split('T')[0];
  const in7Str = in7.toISOString().split('T')[0];
  const in3Str = in3.toISOString().split('T')[0];
  const in1Str = in1.toISOString().split('T')[0];

  let sendType = null;
  let daysUntil = Math.round((celDate - today) / (1000 * 60 * 60 * 24));

  if (celDateStr === todayStr) sendType = 'TODAY';
  else if (celDateStr === in1Str) sendType = '1_DAY_BEFORE';
  else if (celDateStr === in3Str) sendType = '3_DAYS_BEFORE';
  else if (celDateStr === in7Str) sendType = '7_DAYS_BEFORE';

  if (sendType) {
    toSend.push({ ...cel, sendType, daysUntil, todayStr });
  }
}

if (toSend.length === 0) {
  return [{ json: { skip: true, message: 'No celebrations to notify today: ' + todayStr } }];
}

return toSend.map(c => ({ json: c }));

// Summary
const results = $input.all();
const count = results.length;
console.log(`✅ Celebration messages sent: ${count}`);
return [{ json: { status: 'done', messagesSent: count, timestamp: new Date().toISOString() } }];
